const start = $('Start').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.kind);
const base = rows.find(r => r.kind === 'base_cv');
const prof = rows.find(r => r.kind === 'cv_profile');
let profile = {};
try { profile = JSON.parse(prof?.value || '{}'); } catch (e) {}
// only positive facts count as "has the skill"
const extra = rows.filter(r => ['skill', 'experience'].includes(r.kind)).map(r => r.value);
return [{ json: { ...start, has_cv: !!base, base_cv: base?.value || '', profile, extra_facts: extra } }];

// Turn the job page into plain text. Prefer schema.org JobPosting (LinkedIn, Indeed, WTTJ… embed it).
const html = String($input.first().json.data || '');
let text = '';
for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
  try {
    const data = JSON.parse(m[1].trim());
    const list = Array.isArray(data) ? data : (data['@graph'] || [data]);
    const jp = list.find(x => String(x['@type']).includes('JobPosting'));
    if (jp) {
      text = [jp.title, jp.hiringOrganization?.name, jp.description].filter(Boolean).join('\n');
      break;
    }
  } catch (e) {}
}
const strip = s => s
  .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ').replace(/<br\s*\/?>|<\/p>|<\/li>/gi, '\n')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
  .replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
text = text ? strip(text) : strip(html);
return [{ json: { job_text: text.slice(0, 15000), readable: text.length >= 400 } }];

