// Compare the offer's requirements with what we know about the candidate.
const offer = $input.first().json.output || {};
const ctx = $('Load Profile').first().json;
// read the original input: the IF node's unused branch is empty
const pastedText = String($('Start').first().json.text || '');
const jobText = pastedText.length > 150
  ? pastedText
  : ($('Clean Page to Text').isExecuted ? $('Clean Page to Text').first().json.job_text : '');

const norm = s => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9+#. ]/g, ' ').replace(/\.(?= |$)/g, ' ').replace(/\s+/g, ' ').trim();
// profile values only: JSON keys like "tools" or "skills" must not count as matches
const values = o => o && typeof o === 'object' ? Object.values(o).flatMap(values) : [String(o ?? '')];
const haystack = ' ' + norm([ctx.base_cv, ...values(ctx.profile), ...ctx.extra_facts].join(' ')) + ' ';
// whole words only, so "Git" does not match "github" and "Go" does not match "Google"
const has = t => haystack.includes(' ' + t + ' ');
const STOP = new Set(['and', 'or', 'of', 'the', 'with', 'in', 'for', 'de', 'et', 'des', 'la', 'le', 'les', 'du', 'en']);

const reqs = (offer.requirements || []).filter(Boolean);
const matched = [], missing = [];
// a phrase matches if it appears whole, or if all its significant words appear as whole words
const found = phrase => {
  const n = norm(phrase);
  const words = n.split(' ').filter(w => w.length > 1 && !STOP.has(w));
  return has(n) || (words.length > 0 && words.every(has));
};
// the AI suggests strict synonyms / proving tools for each requirement; the code still decides
const aliasesOf = {};
for (const d of (offer.requirements_detail || [])) if (d && d.name) aliasesOf[norm(d.name)] = (d.aliases || []).filter(Boolean);
for (const r of reqs) {
  const hit = found(r) || (aliasesOf[norm(r)] || []).some(found);
  (hit ? matched : missing).push(r);
}
const match_score = reqs.length ? Math.round((10 * matched.length) / reqs.length) : 5;
// missing: the 3 we ask about; missing_all: everything the Generator must never claim
return [{ json: {
  user_id: ctx.user_id, app_id: ctx.app_id, token: ctx.token, url: ctx.url,
  offer, job_text: jobText, matched, missing: missing.slice(0, 3), missing_all: missing, match_score,
} }];
